'use client';
import React, { useState, useEffect, useMemo, useCallback } from 'react';

/* ============================ TYPES ============================ */
type PatientStatus = 'Admitted' | 'Outpatient' | 'Critical' | 'Discharged';
type Role = 'Doctor' | 'Nurse' | 'Technician' | 'Admin';
type View = 'dashboard' | 'patients' | 'staff' | 'settings';
type ThemeKey = 'clinical' | 'noir' | 'emerald' | 'rose';

interface Vitals { hr: number; bp: string; temp: number; }
interface Patient {
  id: string; name: string; age: number; gender: 'Female' | 'Male' | 'Other';
  condition: string; status: PatientStatus; department: string; doctorId: string;
  room: string; admittedOn: string; vitals: Vitals; notes: string[];
}
interface Staff {
  id: string; name: string; role: Role; department: string; shift: 'Day' | 'Night';
  onDuty: boolean; phone: string; photo: string;
}
interface Toast { id: number; text: string; }
interface Draft {
  name: string; age: string; gender: Patient['gender']; condition: string;
  department: string; doctorId: string; critical: boolean;
}

/* ============================ THEMES ============================ */
interface Theme {
  label: string; page: string; card: string; text: string; muted: string;
  accent: string; accentSoft: string; border: string; input: string; swatch: string;
}
const THEMES: Record<ThemeKey, Theme> = {
  clinical: {
    label: 'Clinical Blue', page: 'bg-slate-50', card: 'bg-white', text: 'text-slate-900',
    muted: 'text-slate-500', accent: 'bg-sky-600 text-white hover:bg-sky-700',
    accentSoft: 'bg-sky-100 text-sky-800', border: 'border-slate-200', input: 'bg-slate-100',
    swatch: 'bg-sky-600',
  },
  noir: {
    label: 'Midnight Ward', page: 'bg-zinc-950', card: 'bg-zinc-900', text: 'text-zinc-100',
    muted: 'text-zinc-400', accent: 'bg-amber-400 text-zinc-900 hover:bg-amber-300',
    accentSoft: 'bg-amber-400/15 text-amber-300', border: 'border-zinc-800', input: 'bg-zinc-800',
    swatch: 'bg-amber-400',
  },
  emerald: {
    label: 'Emerald Care', page: 'bg-emerald-950', card: 'bg-emerald-900', text: 'text-emerald-50',
    muted: 'text-emerald-200/70', accent: 'bg-emerald-400 text-emerald-950 hover:bg-emerald-300',
    accentSoft: 'bg-emerald-400/20 text-emerald-200', border: 'border-emerald-800', input: 'bg-emerald-800',
    swatch: 'bg-emerald-400',
  },
  rose: {
    label: 'Rose Daylight', page: 'bg-rose-50', card: 'bg-white', text: 'text-rose-950',
    muted: 'text-rose-900/60', accent: 'bg-rose-500 text-white hover:bg-rose-600',
    accentSoft: 'bg-rose-100 text-rose-700', border: 'border-rose-200', input: 'bg-rose-100',
    swatch: 'bg-rose-500',
  },
};

/* ============================ HELPERS ============================ */
const DEPARTMENTS = ['Cardiology', 'Neurology', 'Pediatrics', 'Orthopedics', 'Emergency', 'General'];
const STATUSES: PatientStatus[] = ['Admitted', 'Outpatient', 'Critical', 'Discharged'];
const ROLES: Role[] = ['Doctor', 'Nurse', 'Technician', 'Admin'];
const TOTAL_BEDS = 24;
const STORAGE_KEY = 'medipulse-state-v1';

export function filterPatients(list: Patient[], query: string, status: PatientStatus | 'All', dept: string): Patient[] {
  const q = query.trim().toLowerCase();
  return list.filter((p) =>
    (status === 'All' || p.status === status) &&
    (dept === 'All' || p.department === dept) &&
    (q === '' || p.name.toLowerCase().includes(q) || p.id.toLowerCase().includes(q) || p.condition.toLowerCase().includes(q)));
}
export function occupiedBeds(list: Patient[]): number {
  return list.filter((p) => p.status === 'Admitted' || p.status === 'Critical').length;
}
export function makeAdmissionId(seq: number): string {
  return `ADM-${String(seq).padStart(5, '0')}`;
}
const statusStyle: Record<PatientStatus, string> = {
  Admitted: 'bg-sky-500/15 text-sky-500', Outpatient: 'bg-violet-500/15 text-violet-500',
  Critical: 'bg-red-500/15 text-red-500', Discharged: 'bg-emerald-500/15 text-emerald-500',
};

const PHOTOS = [
  'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?auto=format&fit=crop&w=400&q=80',
  'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?auto=format&fit=crop&w=400&q=80',
  'https://images.unsplash.com/photo-1582750433449-648ed127bb54?auto=format&fit=crop&w=400&q=80',
  'https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=400&q=80',
];
const SEED_STAFF: Staff[] = [
  { id: 'S-101', name: 'Dr. Meera Kapoor', role: 'Doctor', department: 'Cardiology', shift: 'Day', onDuty: true, phone: '555-0101', photo: PHOTOS[1] },
  { id: 'S-102', name: 'Dr. James Whitaker', role: 'Doctor', department: 'Neurology', shift: 'Day', onDuty: true, phone: '555-0102', photo: PHOTOS[0] },
  { id: 'S-103', name: 'Dr. Aisha Rahman', role: 'Doctor', department: 'Emergency', shift: 'Night', onDuty: false, phone: '555-0103', photo: PHOTOS[2] },
  { id: 'S-201', name: 'Nurse Priya Nair', role: 'Nurse', department: 'Pediatrics', shift: 'Day', onDuty: true, phone: '555-0201', photo: PHOTOS[3] },
  { id: 'S-202', name: 'Nurse Daniel Cho', role: 'Nurse', department: 'Emergency', shift: 'Night', onDuty: true, phone: '555-0202', photo: 'broken' },
  { id: 'S-301', name: 'Lena Fischer', role: 'Technician', department: 'General', shift: 'Day', onDuty: true, phone: '555-0301', photo: 'broken' },
  { id: 'S-401', name: 'Omar Haddad', role: 'Admin', department: 'General', shift: 'Day', onDuty: false, phone: '555-0401', photo: 'broken' },
];
const SEED_PATIENTS: Patient[] = [
  { id: 'ADM-00001', name: 'Rohan Mehta', age: 54, gender: 'Male', condition: 'Chest pain, suspected angina', status: 'Critical', department: 'Cardiology', doctorId: 'S-101', room: 'C-12', admittedOn: '2025-01-12', vitals: { hr: 112, bp: '150/95', temp: 37.4 }, notes: ['ECG ordered', 'Started on beta blockers'] },
  { id: 'ADM-00002', name: 'Sarah Lindqvist', age: 31, gender: 'Female', condition: 'Migraine with aura', status: 'Admitted', department: 'Neurology', doctorId: 'S-102', room: 'N-04', admittedOn: '2025-01-14', vitals: { hr: 78, bp: '118/76', temp: 36.8 }, notes: ['MRI scheduled'] },
  { id: 'ADM-00003', name: 'Tobias Green', age: 8, gender: 'Male', condition: 'Seasonal asthma', status: 'Outpatient', department: 'Pediatrics', doctorId: 'S-101', room: '-', admittedOn: '2025-01-15', vitals: { hr: 96, bp: '100/65', temp: 37.0 }, notes: [] },
  { id: 'ADM-00004', name: 'Fatima Zahra', age: 67, gender: 'Female', condition: 'Hip fracture recovery', status: 'Admitted', department: 'Orthopedics', doctorId: 'S-102', room: 'O-09', admittedOn: '2025-01-10', vitals: { hr: 72, bp: '130/82', temp: 36.7 }, notes: ['Physio twice daily'] },
  { id: 'ADM-00005', name: 'Chen Wei', age: 45, gender: 'Male', condition: 'Appendectomy follow-up', status: 'Discharged', department: 'General', doctorId: 'S-103', room: '-', admittedOn: '2025-01-05', vitals: { hr: 70, bp: '121/79', temp: 36.6 }, notes: ['Sutures removed'] },
];

const EMPTY_DRAFT: Draft = { name: '', age: '', gender: 'Female', condition: '', department: 'General', doctorId: 'S-101', critical: false };

/* ============================ SMALL COMPONENTS ============================ */
function Avatar({ name, src, size = 'h-12 w-12' }: { name: string; src?: string; size?: string }) {
  const [failed, setFailed] = useState(false);
  const initials = name.replace(/^(Dr\.|Nurse)\s/, '').split(' ').map((w) => w[0]).slice(0, 2).join('');
  if (!src || failed || src === 'broken') {
    return <div className={`${size} flex shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-sky-400 to-indigo-500 text-sm font-bold text-white`}>{initials}</div>;
  }
  return <img src={src} alt={name} referrerPolicy='no-referrer' loading='lazy' onError={() => setFailed(true)} className={`${size} shrink-0 rounded-full object-cover`} />;
}

function Chip({ active, onClick, children, t }: { active: boolean; onClick: () => void; children: React.ReactNode; t: Theme }) {
  return (
    <button type='button' onClick={onClick} className={`rounded-full px-3 py-1.5 text-xs font-semibold transition ${active ? t.accent : `${t.input} ${t.muted} hover:opacity-80`}`}>
      {children}
    </button>
  );
}

function Switch({ on, onChange, label }: { on: boolean; onChange: () => void; label: string }) {
  return (
    <button type='button' role='switch' aria-checked={on} aria-label={label} onClick={onChange} className={`relative h-6 w-11 rounded-full transition ${on ? 'bg-emerald-500' : 'bg-slate-400/50'}`}>
      <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-all ${on ? 'left-5' : 'left-0.5'}`} />
    </button>
  );
}

function Field({ label, t, children }: { label: string; t: Theme; children: React.ReactNode }) {
  return (
    <label className='block'>
      <span className={`mb-1 block text-xs font-semibold uppercase tracking-wide ${t.muted}`}>{label}</span>
      {children}
    </label>
  );
}

/* ============================ APP ============================ */
export function App() {
  const [isHydrated, setIsHydrated] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(SEED_PATIENTS);
  const [staff, setStaff] = useState<Staff[]>(SEED_STAFF);
  const [themeKey, setThemeKey] = useState<ThemeKey>('clinical');
  const [view, setView] = useState<View>('dashboard');
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<PatientStatus | 'All'>('All');
  const [deptFilter, setDeptFilter] = useState('All');
  const [roleFilter, setRoleFilter] = useState<Role | 'All'>('All');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [noteText, setNoteText] = useState('');
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [step, setStep] = useState(1);
  const [draft, setDraft] = useState<Draft>(EMPTY_DRAFT);
  const [confirmedId, setConfirmedId] = useState<string | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);

  const t = THEMES[themeKey];

  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const data = JSON.parse(raw);
        if (Array.isArray(data.patients)) setPatients(data.patients);
        if (Array.isArray(data.staff)) setStaff(data.staff);
        if (data.themeKey && THEMES[data.themeKey as ThemeKey]) setThemeKey(data.themeKey);
      }
    } catch { /* ignore corrupted storage */ }
    setIsHydrated(true);
  }, []);

  useEffect(() => {
    if (!isHydrated) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ patients, staff, themeKey }));
  }, [patients, staff, themeKey, isHydrated]);

  const notify = useCallback((text: string) => {
    const id = Date.now() + Math.random();
    setToasts((prev) => [...prev, { id, text }]);
    setTimeout(() => setToasts((prev) => prev.filter((x) => x.id !== id)), 3000);
  }, []);

  const filteredPatients = useMemo(() => filterPatients(patients, query, statusFilter, deptFilter), [patients, query, statusFilter, deptFilter]);
  const filteredStaff = useMemo(() => {
    const q = query.trim().toLowerCase();
    return staff.filter((s) => (roleFilter === 'All' || s.role === roleFilter) && (q === '' || s.name.toLowerCase().includes(q) || s.department.toLowerCase().includes(q)));
  }, [staff, query, roleFilter]);
  const doctors = useMemo(() => staff.filter((s) => s.role === 'Doctor'), [staff]);
  const selected = useMemo(() => patients.find((p) => p.id === selectedId) ?? null, [patients, selectedId]);
  const stats = useMemo(() => ({
    total: patients.length,
    critical: patients.filter((p) => p.status === 'Critical').length,
    beds: occupiedBeds(patients),
    onDuty: staff.filter((s) => s.onDuty).length,
  }), [patients, staff]);

  const doctorName = useCallback((id: string) => staff.find((s) => s.id === id)?.name ?? 'Unassigned', [staff]);

  const updatePatient = useCallback((id: string, patch: Partial<Patient>) => {
    setPatients((prev) => prev.map((p) => (p.id === id ? { ...p, ...patch } : p)));
  }, []);

  const setStatus = useCallback((p: Patient, status: PatientStatus) => {
    const room = status === 'Discharged' || status === 'Outpatient' ? '-' : p.room === '-' ? `W-${Math.floor(Math.random() * 40 + 10)}` : p.room;
    updatePatient(p.id, { status, room });
    notify(`${p.name} marked as ${status}`);
  }, [updatePatient, notify]);

  const addNote = useCallback(() => {
    if (!selected || !noteText.trim()) return;
    updatePatient(selected.id, { notes: [...selected.notes, noteText.trim()] });
    setNoteText('');
    notify('Clinical note saved');
  }, [selected, noteText, updatePatient, notify]);

  const toggleDuty = useCallback((id: string) => {
    setStaff((prev) => prev.map((s) => (s.id === id ? { ...s, onDuty: !s.onDuty } : s)));
  }, []);

  const openDrawer = () => { setDraft(EMPTY_DRAFT); setStep(1); setConfirmedId(null); setDrawerOpen(true); };
  const step1Valid = draft.name.trim().length > 1 && Number(draft.age) > 0 && Number(draft.age) < 121;
  const step2Valid = draft.condition.trim().length > 2;

  const submitAdmission = () => {
    const id = makeAdmissionId(patients.length + 1);
    const p: Patient = {
      id, name: draft.name.trim(), age: Number(draft.age), gender: draft.gender, condition: draft.condition.trim(),
      status: draft.critical ? 'Critical' : 'Admitted', department: draft.department, doctorId: draft.doctorId,
      room: `W-${Math.floor(Math.random() * 40 + 10)}`, admittedOn: new Date().toISOString().slice(0, 10),
      vitals: { hr: 80, bp: '120/80', temp: 36.8 }, notes: [],
    };
    setPatients((prev) => [p, ...prev]);
    setConfirmedId(id);
    setStep(4);
    notify(`${p.name} admitted (${id})`);
  };

  const navItems: { key: View; label: string }[] = [
    { key: 'dashboard', label: 'Dashboard' }, { key: 'patients', label: 'Patients' },
    { key: 'staff', label: 'Staff Directory' }, { key: 'settings', label: 'Settings' },
  ];

  const inputCls = `w-full rounded-xl ${t.input} ${t.text} px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-sky-400`;

  /* ---------- Patient row/card ---------- */
  const PatientCard = ({ p }: { p: Patient }) => (
    <button type='button' onClick={() => setSelectedId(p.id)} className={`group w-full rounded-2xl border ${t.border} ${t.card} p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg`}>
      <div className='flex items-start justify-between gap-2'>
        <div className='flex items-center gap-3'>
          <Avatar name={p.name} />
          <div>
            <p className='font-semibold'>{p.name}</p>
            <p className={`text-xs ${t.muted}`}>{p.id} · {p.age}y · {p.gender}</p>
          </div>
        </div>
        <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${statusStyle[p.status]}`}>{p.status}</span>
      </div>
      <p className={`mt-3 text-sm ${t.muted}`}>{p.condition}</p>
      <div className='mt-3 flex items-center justify-between text-xs'>
        <span className={`rounded-md px-2 py-1 ${t.accentSoft}`}>{p.department}</span>
        <span className={t.muted}>{doctorName(p.doctorId)} · Room {p.room}</span>
      </div>
    </button>
  );

  /* ---------- Views ---------- */
  const dashboard = (
    <div className='space-y-8'>
      <section className={`relative overflow-hidden rounded-3xl ${t.card} border ${t.border} p-8 shadow-sm md:p-12`}>
        <div className={`absolute -right-20 -top-20 h-72 w-72 rounded-full opacity-20 blur-3xl ${t.swatch}`} />
        <p className={`text-xs font-bold uppercase tracking-widest ${t.muted}`}>Hospital Information System</p>
        <h1 className='mt-3 max-w-2xl font-serif text-4xl font-bold leading-tight md:text-5xl'>Every patient. Every caregiver. One living record.</h1>
        <p className={`mt-4 max-w-xl ${t.muted}`}>Replace paper registers with a single, searchable source of truth for admissions, clinical notes, and staff rosters.</p>
        <div className='mt-6 flex flex-wrap gap-3'>
          <button type='button' onClick={openDrawer} className={`rounded-xl px-5 py-3 text-sm font-semibold transition ${t.accent}`}>Admit new patient</button>
          <button type='button' onClick={() => setView('staff')} className={`rounded-xl border ${t.border} px-5 py-3 text-sm font-semibold transition hover:opacity-70`}>View staff roster</button>
        </div>
        <div className='mt-8 grid grid-cols-2 gap-4 md:grid-cols-4'>
          {[['Patients', stats.total], ['Critical', stats.critical], [`Beds used / ${TOTAL_BEDS}`, stats.beds], ['Staff on duty', stats.onDuty]].map(([label, value]) => (
            <div key={String(label)} className={`rounded-2xl ${t.input} p-4`}>
              <p className='text-3xl font-bold'>{value}</p>
              <p className={`text-xs ${t.muted}`}>{label}</p>
            </div>
          ))}
        </div>
      </section>

      <section className='grid gap-6 lg:grid-cols-3'>
        <div className={`rounded-2xl border ${t.border} ${t.card} p-5 lg:col-span-2`}>
          <h2 className='mb-4 text-lg font-bold'>Needs attention</h2>
          <div className='grid gap-3 md:grid-cols-2'>
            {patients.filter((p) => p.status === 'Critical').map((p) => <PatientCard key={p.id} p={p} />)}
            {stats.critical === 0 && <p className={t.muted}>No critical patients right now.</p>}
          </div>
        </div>
        <div className={`rounded-2xl border ${t.border} ${t.card} p-5`}>
          <h2 className='mb-4 text-lg font-bold'>Bed occupancy</h2>
          <div className={`h-3 w-full overflow-hidden rounded-full ${t.input}`}>
            <div className={`h-full rounded-full ${t.swatch} transition-all duration-500`} style={{ width: `${Math.min(100, (stats.beds / TOTAL_BEDS) * 100)}%` }} />
          </div>
          <p className={`mt-2 text-sm ${t.muted}`}>{Math.round((stats.beds / TOTAL_BEDS) * 100)}% of {TOTAL_BEDS} beds occupied</p>
          <h3 className='mb-2 mt-6 text-sm font-bold'>By department</h3>
          {DEPARTMENTS.map((d) => {
            const n = patients.filter((p) => p.department === d).length;
            return (
              <div key={d} className='mb-2 flex items-center justify-between text-sm'>
                <span>{d}</span><span className={`rounded-full px-2 text-xs font-semibold ${t.accentSoft}`}>{n}</span>
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );

  const patientsView = (
    <div className='space-y-5'>
      <div className='flex flex-wrap items-center justify-between gap-3'>
        <h2 className='text-2xl font-bold'>Patient Records <span className={`text-base font-normal ${t.muted}`}>({filteredPatients.length})</span></h2>
        <button type='button' onClick={openDrawer} className={`rounded-xl px-4 py-2 text-sm font-semibold ${t.accent}`}>+ Admit patient</button>
      </div>
      <div className='flex flex-wrap gap-2'>
        <Chip t={t} active={statusFilter === 'All'} onClick={() => setStatusFilter('All')}>All statuses</Chip>
        {STATUSES.map((s) => <Chip key={s} t={t} active={statusFilter === s} onClick={() => setStatusFilter(s)}>{s}</Chip>)}
      </div>
      <div className='flex flex-wrap gap-2'>
        <Chip t={t} active={deptFilter === 'All'} onClick={() => setDeptFilter('All')}>All departments</Chip>
        {DEPARTMENTS.map((d) => <Chip key={d} t={t} active={deptFilter === d} onClick={() => setDeptFilter(d)}>{d}</Chip>)}
      </div>
      {filteredPatients.length === 0 ? (
        <div className={`rounded-2xl border border-dashed ${t.border} p-12 text-center ${t.muted}`}>No patients match your filters.</div>
      ) : (
        <div className='grid gap-4 md:grid-cols-2 xl:grid-cols-3'>{filteredPatients.map((p) => <PatientCard key={p.id} p={p} />)}</div>
      )}
    </div>
  );

  const staffView = (
    <div className='space-y-5'>
      <h2 className='text-2xl font-bold'>Staff Directory <span className={`text-base font-normal ${t.muted}`}>({filteredStaff.length})</span></h2>
      <div className='flex flex-wrap gap-2'>
        <Chip t={t} active={roleFilter === 'All'} onClick={() => setRoleFilter('All')}>Everyone</Chip>
        {ROLES.map((r) => <Chip key={r} t={t} active={roleFilter === r} onClick={() => setRoleFilter(r)}>{r}s</Chip>)}
      </div>
      <div className='grid gap-4 md:grid-cols-2 xl:grid-cols-3'>
        {filteredStaff.map((s) => (
          <div key={s.id} className={`group rounded-2xl border ${t.border} ${t.card} p-4 shadow-sm`}>
            <div className='flex items-center gap-3'>
              <div className='overflow-hidden rounded-full'><Avatar name={s.name} src={s.photo} size='h-16 w-16 transition-transform duration-500 group-hover:scale-105' /></div>
              <div className='flex-1'>
                <p className='font-semibold'>{s.name}</p>
                <p className={`text-xs ${t.muted}`}>{s.role} · {s.department}</p>
                <p className={`text-xs ${t.muted}`}>{s.shift} shift · {s.phone}</p>
              </div>
            </div>
            <div className='mt-4 flex items-center justify-between'>
              <span className={`text-xs font-semibold ${s.onDuty ? 'text-emerald-500' : t.muted}`}>{s.onDuty ? 'On duty' : 'Off duty'}</span>
              <Switch on={s.onDuty} label={`Toggle duty for ${s.name}`} onChange={() => { toggleDuty(s.id); notify(`${s.name} is now ${s.onDuty ? 'off' : 'on'} duty`); }} />
            </div>
          </div>
        ))}
      </div>
      {filteredStaff.length === 0 && <div className={`rounded-2xl border border-dashed ${t.border} p-12 text-center ${t.muted}`}>No staff found.</div>}
    </div>
  );

  const settingsView = (
    <div className='max-w-2xl space-y-6'>
      <h2 className='text-2xl font-bold'>Settings</h2>
      <div className={`rounded-2xl border ${t.border} ${t.card} p-5`}>
        <h3 className='mb-3 font-bold'>Appearance</h3>
        <div className='grid grid-cols-2 gap-3'>
          {(Object.keys(THEMES) as ThemeKey[]).map((k) => (
            <button key={k} type='button' onClick={() => setThemeKey(k)} className={`flex items-center gap-3 rounded-xl border p-3 text-left text-sm transition ${themeKey === k ? 'border-sky-500 ring-2 ring-sky-400' : t.border}`}>
              <span className={`h-6 w-6 rounded-full ${THEMES[k].swatch}`} />{THEMES[k].label}
            </button>
          ))}
        </div>
      </div>
      <div className={`rounded-2xl border ${t.border} ${t.card} p-5`}>
        <h3 className='mb-1 font-bold'>Data</h3>
        <p className={`mb-3 text-sm ${t.muted}`}>Records are saved in this browser. Reset restores the demo dataset.</p>
        <button type='button' onClick={() => { setPatients(SEED_PATIENTS); setStaff(SEED_STAFF); notify('Demo data restored'); }} className={`rounded-xl px-4 py-2 text-sm font-semibold ${t.accent}`}>Reset demo data</button>
      </div>
    </div>
  );

  /* ---------- Render ---------- */
  return (
    <div className={`min-h-screen ${t.page} ${t.text} font-sans transition-colors`}>
      <header className={`sticky top-0 z-30 border-b ${t.border} ${t.card}/90 backdrop-blur`}>
        <div className='mx-auto flex max-w-7xl flex-wrap items-center gap-4 px-4 py-3'>
          <div className='flex items-center gap-2'>
            <span className={`flex h-9 w-9 items-center justify-center rounded-xl text-lg font-black ${t.accent}`}>+</span>
            <span className='text-lg font-extrabold tracking-tight'>MediPulse</span>
          </div>
          <nav className='flex gap-1 overflow-x-auto'>
            {navItems.map((n) => (
              <button key={n.key} type='button' onClick={() => setView(n.key)} className={`rounded-lg px-3 py-2 text-sm font-semibold transition ${view === n.key ? t.accent : `${t.muted} hover:opacity-70`}`}>{n.label}</button>
            ))}
          </nav>
          <div className='ml-auto flex items-center gap-3'>
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder='Search name, ID, condition...' className={`w-52 rounded-full ${t.input} px-4 py-2 text-sm outline-none focus:ring-2 focus:ring-sky-400 md:w-72`} />
            <div className='hidden gap-1.5 sm:flex'>
              {(Object.keys(THEMES) as ThemeKey[]).map((k) => (
                <button key={k} type='button' aria-label={THEMES[k].label} title={THEMES[k].label} onClick={() => setThemeKey(k)} className={`h-6 w-6 rounded-full ${THEMES[k].swatch} ${themeKey === k ? 'ring-2 ring-offset-2 ring-sky-400' : ''}`} />
              ))}
            </div>
          </div>
        </div>
      </header>

      <main className='mx-auto max-w-7xl px-4 py-8'>
        {view === 'dashboard' && dashboard}
        {view === 'patients' && patientsView}
        {view === 'staff' && staffView}
        {view === 'settings' && settingsView}
      </main>

      {/* Patient detail modal */}
      {selected && (
        <div className='fixed inset-0 z-40 flex items-center justify-center bg-black/60 p-4' onClick={() => setSelectedId(null)}>
          <div className={`max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-3xl ${t.card} ${t.text} p-6 shadow-2xl`} onClick={(e) => e.stopPropagation()}>
            <div className='flex items-start justify-between'>
              <div className='flex items-center gap-4'>
                <Avatar name={selected.name} size='h-16 w-16' />
                <div>
                  <h3 className='text-2xl font-bold'>{selected.name}</h3>
                  <p className={`text-sm ${t.muted}`}>{selected.id} · {selected.age}y · {selected.gender} · Admitted {selected.admittedOn}</p>
                </div>
              </div>
              <button type='button' aria-label='Close' onClick={() => setSelectedId(null)} className={`rounded-full ${t.input} px-3 py-1`}>✕</button>
            </div>
            <p className='mt-4 text-sm'>{selected.condition}</p>
            <div className='mt-4 grid grid-cols-3 gap-3 text-center'>
              {[['Heart rate', `${selected.vitals.hr} bpm`], ['Blood pressure', selected.vitals.bp], ['Temperature', `${selected.vitals.temp} °C`]].map(([k, v]) => (
                <div key={k} className={`rounded-xl ${t.input} p-3`}><p className='font-bold'>{v}</p><p className={`text-xs ${t.muted}`}>{k}</p></div>
              ))}
            </div>
            <h4 className='mb-2 mt-5 text-sm font-bold'>Status</h4>
            <div className='flex flex-wrap gap-2'>
              {STATUSES.map((s) => <Chip key={s} t={t} active={selected.status === s} onClick={() => setStatus(selected, s)}>{s}</Chip>)}
            </div>
            <h4 className='mb-2 mt-5 text-sm font-bold'>Attending doctor</h4>
            <div className='flex flex-wrap gap-2'>
              {doctors.map((d) => <Chip key={d.id} t={t} active={selected.doctorId === d.id} onClick={() => { updatePatient(selected.id, { doctorId: d.id }); notify(`Assigned to ${d.name}`); }}>{d.name}</Chip>)}
            </div>
            <h4 className='mb-2 mt-5 text-sm font-bold'>Clinical notes</h4>
            <ul className='space-y-2'>
              {selected.notes.map((n, i) => <li key={i} className={`rounded-lg ${t.input} px-3 py-2 text-sm`}>{n}</li>)}
              {selected.notes.length === 0 && <li className={`text-sm ${t.muted}`}>No notes yet.</li>}
            </ul>
            <div className='mt-3 flex gap-2'>
              <input value={noteText} onChange={(e) => setNoteText(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') addNote(); }} placeholder='Add a clinical note' className={inputCls} />
              <button type='button' onClick={addNote} disabled={!noteText.trim()} className={`rounded-xl px-4 text-sm font-semibold disabled:opacity-40 ${t.accent}`}>Save</button>
            </div>
          </div>
        </div>
      )}

      {/* Admission drawer */}
      {drawerOpen && (
        <div className='fixed inset-0 z-50 flex justify-end bg-black/60' onClick={() => setDrawerOpen(false)}>
          <aside className={`flex h-full w-full max-w-md flex-col ${t.card} ${t.text} p-6 shadow-2xl`} onClick={(e) => e.stopPropagation()}>
            <div className='flex items-center justify-between'>
              <h3 className='text-xl font-bold'>{step === 4 ? 'Admission complete' : 'New admission'}</h3>
              <button type='button' aria-label='Close drawer' onClick={() => setDrawerOpen(false)} className={`rounded-full ${t.input} px-3 py-1`}>✕</button>
            </div>
            {step < 4 && (
              <div className='mt-4 flex gap-2'>
                {[1, 2, 3].map((n) => <div key={n} className={`h-1.5 flex-1 rounded-full ${n <= step ? t.swatch : t.input}`} />)}
              </div>
            )}
            <div className='mt-6 flex-1 space-y-4 overflow-y-auto'>
              {step === 1 && (
                <>
                  <Field label='Full name' t={t}><input className={inputCls} value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></Field>
                  <Field label='Age' t={t}><input className={inputCls} inputMode='numeric' value={draft.age} onChange={(e) => setDraft({ ...draft, age: e.target.value.replace(/\D/g, '') })} /></Field>
                  <Field label='Gender' t={t}>
                    <div className='flex gap-2'>{(['Female', 'Male', 'Other'] as const).map((g) => <Chip key={g} t={t} active={draft.gender === g} onClick={() => setDraft({ ...draft, gender: g })}>{g}</Chip>)}</div>
                  </Field>
                </>
              )}
              {step === 2 && (
                <>
                  <Field label='Condition / reason for admission' t={t}><textarea rows={3} className={inputCls} value={draft.condition} onChange={(e) => setDraft({ ...draft, condition: e.target.value })} /></Field>
                  <Field label='Department' t={t}>
                    <div className='flex flex-wrap gap-2'>{DEPARTMENTS.map((d) => <Chip key={d} t={t} active={draft.department === d} onClick={() => setDraft({ ...draft, department: d })}>{d}</Chip>)}</div>
                  </Field>
                  <Field label='Attending doctor' t={t}>
                    <div className='flex flex-wrap gap-2'>{doctors.map((d) => <Chip key={d.id} t={t} active={draft.doctorId === d.id} onClick={() => setDraft({ ...draft, doctorId: d.id })}>{d.name}</Chip>)}</div>
                  </Field>
                  <div className='flex items-center justify-between'>
                    <span className='text-sm font-semibold'>Mark as critical</span>
                    <Switch on={draft.critical} label='Critical' onChange={() => setDraft({ ...draft, critical: !draft.critical })} />
                  </div>
                </>
              )}
              {step === 3 && (
                <div className={`space-y-2 rounded-2xl ${t.input} p-4 text-sm`}>
                  <p><b>{draft.name}</b>, {draft.age}y, {draft.gender}</p>
                  <p>{draft.condition}</p>
                  <p className={t.muted}>{draft.department} · {doctorName(draft.doctorId)}</p>
                  <p className={draft.critical ? 'font-bold text-red-500' : t.muted}>{draft.critical ? 'Critical priority' : 'Standard priority'}</p>
                </div>
              )}
              {step === 4 && confirmedId && (
                <div className='py-10 text-center'>
                  <div className='mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-emerald-500 text-3xl text-white'>✓</div>
                  <p className='mt-4 text-lg font-bold'>{draft.name} has been admitted</p>
                  <p className={`mt-1 text-sm ${t.muted}`}>Admission ID</p>
                  <p className='font-mono text-2xl font-bold'>{confirmedId}</p>
                </div>
              )}
            </div>
            <div className='mt-4 flex gap-3'>
              {step > 1 && step < 4 && <button type='button' onClick={() => setStep(step - 1)} className={`flex-1 rounded-xl border ${t.border} py-3 text-sm font-semibold`}>Back</button>}
              {step === 1 && <button type='button' disabled={!step1Valid} onClick={() => setStep(2)} className={`flex-1 rounded-xl py-3 text-sm font-semibold disabled:opacity-40 ${t.accent}`}>Continue</button>}
              {step === 2 && <button type='button' disabled={!step2Valid} onClick={() => setStep(3)} className={`flex-1 rounded-xl py-3 text-sm font-semibold disabled:opacity-40 ${t.accent}`}>Review</button>}
              {step === 3 && <button type='button' onClick={submitAdmission} className={`flex-1 rounded-xl py-3 text-sm font-semibold ${t.accent}`}>Confirm admission</button>}
              {step === 4 && <button type='button' onClick={() => { setDrawerOpen(false); setView('patients'); }} className={`flex-1 rounded-xl py-3 text-sm font-semibold ${t.accent}`}>View patient records</button>}
            </div>
          </aside>
        </div>
      )}

      {/* Toasts */}
      <div className='fixed bottom-4 left-1/2 z-[60] flex -translate-x-1/2 flex-col gap-2'>
        {toasts.map((x) => <div key={x.id} className='rounded-full bg-slate-900 px-4 py-2 text-sm text-white shadow-lg'>{x.text}</div>)}
      </div>
    </div>
  );
}

