import { test, expect } from "bun:test";

type Status = "Admitted" | "Outpatient" | "Critical" | "Discharged";
interface P { id: string; name: string; status: Status; department: string; condition: string; }

// Domain logic mirrored from src/components/App.tsx (pure functions)
function filterPatients(list: P[], query: string, status: Status | "All", dept: string): P[] {
  const q = query.trim().toLowerCase();
  return list.filter((p) =>
    (status === "All" || p.status === status) &&
    (dept === "All" || p.department === dept) &&
    (q === "" || p.name.toLowerCase().includes(q) || p.id.toLowerCase().includes(q) || p.condition.toLowerCase().includes(q)));
}
function occupiedBeds(list: P[]): number {
  return list.filter((p) => p.status === "Admitted" || p.status === "Critical").length;
}
function makeAdmissionId(seq: number): string {
  return `ADM-${String(seq).padStart(5, "0")}`;
}
function setStatus(p: P, status: Status): P {
  return { ...p, status };
}

const data: P[] = [
  { id: "ADM-00001", name: "Rohan Mehta", status: "Critical", department: "Cardiology", condition: "Chest pain" },
  { id: "ADM-00002", name: "Sarah Lindqvist", status: "Admitted", department: "Neurology", condition: "Migraine" },
  { id: "ADM-00003", name: "Tobias Green", status: "Outpatient", department: "Pediatrics", condition: "Asthma" },
  { id: "ADM-00004", name: "Chen Wei", status: "Discharged", department: "General", condition: "Follow-up" },
];

test("search matches name, id and condition case-insensitively", () => {
  expect(filterPatients(data, "rohan", "All", "All").length).toBe(1);
  expect(filterPatients(data, "adm-00002", "All", "All").length).toBe(1);
  expect(filterPatients(data, "ASTHMA", "All", "All")[0].name).toBe("Tobias Green");
});

test("status and department filters combine with AND logic", () => {
  expect(filterPatients(data, "", "Critical", "Cardiology").length).toBe(1);
  expect(filterPatients(data, "", "Critical", "Neurology").length).toBe(0);
});

test("empty query with All filters returns every patient", () => {
  expect(filterPatients(data, "   ", "All", "All").length).toBe(data.length);
});

test("bed occupancy counts only admitted and critical patients", () => {
  expect(occupiedBeds(data)).toBe(2);
});

test("admission IDs are zero-padded and unique per sequence", () => {
  expect(makeAdmissionId(7)).toBe("ADM-00007");
  expect(makeAdmissionId(123)).not.toBe(makeAdmissionId(124));
});

test("status transition is immutable and reduces occupancy on discharge", () => {
  const discharged = setStatus(data[0], "Discharged");
  expect(discharged.status).toBe("Discharged");
  expect(data[0].status).toBe("Critical");
  expect(occupiedBeds([discharged, data[1]])).toBe(1);
});

